CREATE DATABASE IF NOT EXISTS afims_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE afims_db;
CREATE TABLE institutions(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(180) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE departments(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(160) NOT NULL UNIQUE,code VARCHAR(30),institution_id BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(institution_id) REFERENCES institutions(id));
CREATE TABLE users(id BIGINT PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(30) NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('STUDENT','FACULTY','HOD','ADMIN') NOT NULL,status ENUM('PENDING','ACTIVE','REJECTED','SUSPENDED') NOT NULL DEFAULT 'PENDING',institution VARCHAR(180),department VARCHAR(160),institution_id VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_users_role(role),INDEX idx_users_status(status));
CREATE TABLE courses(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(180) NOT NULL,department_id BIGINT,FOREIGN KEY(department_id) REFERENCES departments(id));
CREATE TABLE subjects(id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(40),name VARCHAR(180) NOT NULL,course_id BIGINT,FOREIGN KEY(course_id) REFERENCES courses(id));
CREATE TABLE feedback_cycles(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(180) NOT NULL,academic_year VARCHAR(20),semester INT,start_date DATE,end_date DATE,status ENUM('UPCOMING','ACTIVE','CLOSED') NOT NULL,INDEX idx_cycle_status(status));
CREATE TABLE questions(id BIGINT PRIMARY KEY AUTO_INCREMENT,question_text VARCHAR(500) NOT NULL,category VARCHAR(100),rating_type VARCHAR(40) DEFAULT 'RATING_1_5',required_flag BOOLEAN DEFAULT TRUE,active BOOLEAN DEFAULT TRUE,display_order INT,target_role VARCHAR(30) DEFAULT 'STUDENT',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE feedback(id BIGINT PRIMARY KEY AUTO_INCREMENT,student_id BIGINT NOT NULL,faculty_id BIGINT NOT NULL,course VARCHAR(180) NOT NULL,subject VARCHAR(180),cycle_id BIGINT NOT NULL,overall_rating INT NOT NULL,anonymous BOOLEAN DEFAULT FALSE,comment VARCHAR(2000),suggestion VARCHAR(1000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_feedback_duplicate UNIQUE(student_id,faculty_id,course,cycle_id),FOREIGN KEY(student_id) REFERENCES users(id),FOREIGN KEY(faculty_id) REFERENCES users(id),FOREIGN KEY(cycle_id) REFERENCES feedback_cycles(id),INDEX idx_feedback_faculty(faculty_id),INDEX idx_feedback_student(student_id));
CREATE TABLE feedback_answers(id BIGINT PRIMARY KEY AUTO_INCREMENT,feedback_id BIGINT NOT NULL,question_id BIGINT NOT NULL,rating_value INT,text_value VARCHAR(2000),FOREIGN KEY(feedback_id) REFERENCES feedback(id) ON DELETE CASCADE,FOREIGN KEY(question_id) REFERENCES questions(id));
CREATE TABLE improvement_plans(id BIGINT PRIMARY KEY AUTO_INCREMENT,faculty_id BIGINT NOT NULL,title VARCHAR(200) NOT NULL,problem_statement VARCHAR(2000),evidence VARCHAR(2000),root_cause VARCHAR(1000),proposed_action VARCHAR(2000),target_date DATE,priority VARCHAR(20),expected_outcome VARCHAR(2000),measurement_method VARCHAR(2000),status ENUM('DRAFT','SUBMITTED','UNDER_REVIEW','APPROVED','CHANGES_REQUESTED','REJECTED','IMPLEMENTING','COMPLETED') NOT NULL DEFAULT 'DRAFT',hod_comments VARCHAR(2000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(faculty_id) REFERENCES users(id),INDEX idx_plan_status(status));
CREATE TABLE improvement_plan_history(id BIGINT PRIMARY KEY AUTO_INCREMENT,plan_id BIGINT NOT NULL,status VARCHAR(40),comment VARCHAR(2000),changed_by BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(plan_id) REFERENCES improvement_plans(id) ON DELETE CASCADE,FOREIGN KEY(changed_by) REFERENCES users(id));
CREATE TABLE notifications(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,title VARCHAR(180),message VARCHAR(1000),type VARCHAR(40),read_flag BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_notifications_user(user_id,read_flag));
CREATE TABLE audit_logs(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,action VARCHAR(120),entity_name VARCHAR(100),entity_id BIGINT,ip_address VARCHAR(80),timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),INDEX idx_audit_time(timestamp));
